/* Browser-local review threads and immutable file snapshots. */
(function(PF){
'use strict';
const E=PF.e, comparisons=new Map(), textChoices=new Map(); let clientFilter='';
const types=['image/png','image/jpeg','image/webp','application/pdf','text/plain'];
const deliverable=id=>PF.db.deliverables.find(d=>d.id===id);
const version=(d,id)=>d&&d.versions.find(v=>v.id===id);
const latest=d=>d.versions[d.versions.length-1];
function text(value,max=12000,required=true){if(typeof value!=='string'||value.length>max||(required&&!value.trim()))throw Error('Enter valid text within the field limit.');return value.trim();}
function stamp(v){return typeof v==='string'&&Number.isFinite(Date.parse(v));}
function bytes(asset){
 // The server may reuse an exact-content validation receipt; browsers always validate bytes.
 if(PF.verifiedAsset?.(asset))return new Uint8Array(0);
 if(!types.includes(asset.mime)||typeof asset.data!=='string'||!Number.isInteger(asset.size)||asset.size<1||asset.size>1048576)throw Error('Files must be PNG, JPEG, WEBP, PDF or plain text, up to 1 MiB.');
 const prefix='data:'+asset.mime+';base64,';
 if(!asset.data.startsWith(prefix))throw Error('The stored file type does not match its data.');
 const base=asset.data.slice(prefix.length);
 if(base.length>1398104||! /^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(base))throw Error('Invalid file encoding.');
 let raw;try{raw=atob(base)}catch{throw Error('Invalid file encoding.');}
 if(raw.length!==asset.size||btoa(raw)!==base)throw Error('The stored file size is invalid.');
 const n=i=>raw.charCodeAt(i), has=(s,o=0)=>raw.slice(o,o+s.length)===s;
 if(asset.mime==='image/png'&&!(raw.length>=24&&n(0)===137&&has('PNG\r\n\x1a\n',1)&&has('IHDR',12)))throw Error('Invalid PNG file.');
 if(asset.mime==='image/jpeg'&&!(n(0)===255&&n(1)===216&&n(2)===255&&n(raw.length-2)===255&&n(raw.length-1)===217))throw Error('Invalid JPEG file.');
 if(asset.mime==='image/webp'&&!(has('RIFF')&&has('WEBP',8)&&['VP8 ','VP8L','VP8X'].includes(raw.slice(12,16))))throw Error('Invalid WEBP file.');
 if(asset.mime==='application/pdf'&&!has('%PDF-'))throw Error('Invalid PDF file.');
 if(asset.mime==='text/plain'){try{new TextDecoder('utf-8',{fatal:true}).decode(Uint8Array.from(raw,c=>c.charCodeAt(0)))}catch{throw Error('Plain text must use UTF-8 encoding.');}if(raw.includes('\0'))throw Error('Invalid plain text file.');}
 return Uint8Array.from(raw,c=>c.charCodeAt(0));
}
PF.validators.push((w,data)=>{
 for(const c of w.comments){const d=data.deliverables.find(d=>d.id===c.deliverableId);if(!d||!version(d,c.versionId)||typeof c.resolved!=='boolean'||!Array.isArray(c.replies)||!stamp(c.createdAt))throw Error('Invalid version comment.');text(c.body);text(c.author,254);text(c.anchor,500,false);if(c.replies.length>500||new Set(c.replies.map(r=>r.id)).size!==c.replies.length)throw Error('Invalid replies.');for(const r of c.replies){text(r.id,200);text(r.body);text(r.author,254);if(!stamp(r.createdAt))throw Error('Invalid reply date.');}}
 for(const a of w.assets){if(!data.projects.some(p=>p.id===a.projectId)||!stamp(a.createdAt))throw Error('Invalid file project or date.');text(a.name,250);if(/[\x00-\x1f\x7f]/.test(a.name)||/\.(svg|html?|xhtml)$/i.test(a.name))throw Error('Unsafe file name.');if(typeof a.deliverableId!=='string'||typeof a.versionId!=='string')throw Error('Invalid file version.');if(a.deliverableId||a.versionId){const d=data.deliverables.find(d=>d.id===a.deliverableId);if(!d||d.projectId!==a.projectId||!version(d,a.versionId))throw Error('Invalid file version.');}bytes(a);}
});
function assetCards(items){return items.map(a=>`<div class="card file-card">${a.mime.startsWith('image/')?`<img src="${E(a.data)}" alt="${E(a.name)}" loading="lazy" style="max-width:100%;max-height:180px;object-fit:contain">`:''}<b>${E(a.name)}</b><p class="meta">${E(a.mime)} · ${(a.size/1024).toFixed(1)} KiB · ${E(PF.date(a.createdAt))}</p>${PF.button('Download snapshot','pf-file-download',a.id)}</div>`).join('')||PF.empty('No file snapshots attached.');}
function filesFor(d,v){return PF.w.assets.filter(a=>a.deliverableId===d.id&&a.versionId===v.id);}
function comparePanel(d,v,side){return `<section class="card"><label>${side==='a'?'First':'Second'} version<select data-pf-compare="${side}" data-deliverable="${E(d.id)}">${d.versions.map(x=>`<option value="${E(x.id)}" ${v.id===x.id?'selected':''}>Version ${E(x.number)} · ${E(x.status)}</option>`).join('')}</select></label><h4>Version ${E(v.number)} · ${E(v.status)}</h4><p class="preserve-lines">${E(v.note)}</p>${v.url?`<a href="${E(PF.safeUrl(v.url))}" target="_blank" rel="noopener noreferrer">Open version reference ↗</a>`:''}<div class="space-top">${assetCards(filesFor(d,v))}</div></section>`;}
const diffPresentation={
 added:{background:'background:color-mix(in srgb, #22c55e 12%, transparent)',label:'Added line',marker:'+',tag:'ins'},
 removed:{background:'background:color-mix(in srgb, #ef4444 12%, transparent)',label:'Removed line',marker:'−',tag:'del'},
 same:{background:'',label:'Unchanged line',marker:' ',tag:''}
};
function renderDiffLine([kind,line]){
 const presentation=diffPresentation[kind],escaped=E(line),content=presentation.tag?`<${presentation.tag}>${escaped}</${presentation.tag}>`:escaped||'&nbsp;';
 return `<div role="listitem" class="pf-diff-${kind}" style="white-space:pre-wrap;${presentation.background}"><span aria-label="${presentation.label}">${presentation.marker}</span> ${content}</div>`;
}
// A bounded line LCS keeps comparison work at most 40,000 cells per text pair.
function lineDiff(first,second){
 const bounded=value=>{const normalized=String(value||'').replace(/\r\n?/g,'\n'),prefix=normalized.slice(0,12000),lines=prefix?prefix.split('\n'):[];return {lines:lines.slice(0,200),limited:normalized.length>12000||lines.length>200};};
 const a=bounded(first),b=bounded(second),width=b.lines.length+1,table=new Uint16Array((a.lines.length+1)*width),rows=[];
 for(let i=a.lines.length-1;i>=0;i--)for(let j=b.lines.length-1;j>=0;j--)table[i*width+j]=a.lines[i]===b.lines[j]?table[(i+1)*width+j+1]+1:Math.max(table[(i+1)*width+j],table[i*width+j+1]);
 let i=0,j=0;while(i<a.lines.length||j<b.lines.length){if(i<a.lines.length&&j<b.lines.length&&a.lines[i]===b.lines[j])rows.push(['same',a.lines[i++]]),j++;else if(i<a.lines.length&&(j===b.lines.length||table[(i+1)*width+j]>=table[i*width+j+1]))rows.push(['removed',a.lines[i++]]);else rows.push(['added',b.lines[j++]]);}
 const limited=a.limited||b.limited,changed=rows.some(([kind])=>kind!=='same');
 const notice=limited?'<p class="meta" role="note">Comparison limited to the first 200 lines and 12,000 characters of each text; the rest has not been compared.</p>':'';
 if(!changed)return notice+`<p>${rows.length?(limited?'No changes in the compared portion.':'No text changes.'):'Both texts are empty.'}</p>`;
 return notice+'<p class="meta">− Removed from the first version · + Added in the second version. Line ending styles are treated equally.</p><div class="pf-text-diff" role="list" style="overflow-wrap:anywhere">'+rows.map(renderDiffLine).join('')+'</div>';
}
function textFiles(d,v){return filesFor(d,v).filter(a=>a.mime==='text/plain');}
function chosenText(d,v,side){const choices=textChoices.get(d.id),choice=choices&&choices[side],files=textFiles(d,v);return choice&&choice.versionId===v.id?files.find(a=>a.id===choice.id):files[0];}
function textSelector(d,v,side){const selected=chosenText(d,v,side);return `<label>${side==='a'?'First':'Second'} version plain-text snapshot<select data-pf-textfile="${side}" data-deliverable="${E(d.id)}"><option value="" ${!selected?'selected':''}>No file (empty text)</option>${textFiles(d,v).map(a=>`<option value="${E(a.id)}" ${a.id===selected?.id?'selected':''}>${E(a.name)}</option>`).join('')}</select></label>`;}
function compareChanges(d,a,b){
 const first=chosenText(d,a,'a'),second=chosenText(d,b,'b');
 // File snapshots are validated immutable UTF-8 bytes, never fetched from reference URLs.
 const content=asset=>asset?new TextDecoder('utf-8',{fatal:true}).decode(bytes(asset)):'';
 return `<section class="card space-top" aria-label="Version note changes"><h4>Version note changes</h4>${lineDiff(a.note,b.note)}</section><section class="card space-top" aria-label="Plain-text file changes"><h4>Plain-text file changes</h4><div class="proof-compare" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:16px">${textSelector(d,a,'a')}${textSelector(d,b,'b')}</div>${first||second?lineDiff(content(first),content(second)):'<p>Choose a plain-text snapshot to compare.</p>'}</section>`;
}
function commentsFor(d,isPortal){const rows=PF.w.comments.filter(c=>c.deliverableId===d.id);return rows.map(c=>{const v=version(d,c.versionId);return `<article class="card"><div class="row"><b>Version ${E(v.number)} · ${E(c.author)}</b><span class="badge">${c.resolved?'Resolved':'Open'}</span></div><p class="meta">${E(c.anchor||'General version feedback')} · ${E(PF.date(c.createdAt))}</p><p class="preserve-lines">${E(c.body)}</p>${c.replies.map(r=>`<div class="history"><b>${E(r.author)}</b><p class="preserve-lines">${E(r.body)}</p><span class="meta">${E(PF.date(r.createdAt))}</span></div>`).join('')}<div class="actions">${PF.button('Reply','pf-comment-reply',c.id+(isPortal?'|client':'|agency'))}${PF.button(c.resolved?'Reopen':'Resolve','pf-comment-toggle',c.id)}</div></article>`}).join('')||PF.empty('No version comments yet.');}
PF.deliverableSections.push((d,isPortal)=>{const pair=comparisons.get(d.id)||[d.versions[Math.max(0,d.versions.length-2)].id,latest(d).id],a=version(d,pair[0])||d.versions[0],b=version(d,pair[1])||latest(d);return `<section class="card proofing-section"><div class="section-heading"><h3>Review workspace · ${E(d.title)}</h3>${PF.button('Download approval report','pf-approval-report',d.id)}</div><p class="meta">Version notes and plain-text snapshots support line comparison. Location anchors are page, time or location text. PDF/image differences, drawings and synchronized video review are unavailable.</p><div class="actions">${PF.button('Add version comment','pf-comment-new',d.id+(isPortal?'|client':'|agency'))}${isPortal?'':PF.button('Attach to current version','pf-file-upload',d.id)}</div><details class="space-top" data-pf-comparison="${E(d.id)}" ${comparisons.has(d.id)?'open':''}><summary>Compare any two versions</summary><div class="proof-compare" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:16px">${comparePanel(d,a,'a')}${comparePanel(d,b,'b')}</div>${compareChanges(d,a,b)}</details><h4>Current version file snapshots</h4><div class="project-grid">${assetCards(filesFor(d,latest(d)))}</div><details class="space-top" open><summary>Version comments (${PF.w.comments.filter(c=>c.deliverableId===d.id).length})</summary>${commentsFor(d,isPortal)}</details></section>`;});
function target(b){const [id,mode]=b.dataset.id.split('|');return {id,author:mode==='client'?'Client preview':'Agency'};}
PF.actions['pf-comment-new']=b=>{const {id,author}=target(b),d=deliverable(id);if(!d)throw Error('Deliverable not found.');PF.form('Add version comment',PF.select('versionId','Version reviewed',d.versions.map(v=>[v.id,'Version '+v.number]),latest(d).id)+PF.field('anchor','Page / time / location (text anchor)','text','',false)+PF.area('body','Comment',true),f=>{const live=deliverable(id);if(!version(live,f.versionId))throw Error('Version not found.');PF.w.comments.push({id:PF.id(),deliverableId:id,versionId:f.versionId,body:text(f.body),author,anchor:text(f.anchor,500,false),resolved:false,replies:[],createdAt:PF.now()});PF.log('comment','Added a version comment',live.projectId);});};
PF.actions['pf-comment-reply']=b=>{const {id,author}=target(b);if(!PF.w.comments.some(c=>c.id===id))throw Error('Comment not found.');PF.form('Reply to version comment',PF.area('body','Reply',true),f=>{const c=PF.w.comments.find(c=>c.id===id);if(!c)throw Error('Comment not found.');c.replies.push({id:PF.id(),body:text(f.body),author,createdAt:PF.now()});PF.log('comment','Replied to a version comment',deliverable(c.deliverableId).projectId);});};
PF.actions['pf-comment-toggle']=b=>PF.change(()=>{const c=PF.w.comments.find(c=>c.id===b.dataset.id);if(!c)throw Error('Comment not found.');c.resolved=!c.resolved;PF.log('comment',c.resolved?'Resolved a version comment':'Reopened a version comment',deliverable(c.deliverableId).projectId);});
PF.actions['pf-file-upload']=b=>{
 const d=deliverable(b.dataset.id);if(!d)throw Error('Deliverable not found.');const did=d.id,vid=latest(d).id;
 if(latest(d).status!=='pending')throw Error('Submit a new version before attaching files. This version already has a review decision.');
 const input=document.createElement('input');input.type='file';input.accept='.png,.jpg,.jpeg,.webp,.pdf,.txt';
 input.onchange=()=>{const file=input.files&&input.files[0];if(!file)return;if(!types.includes(file.type)||file.size<1||file.size>1048576||/\.(svg|html?|xhtml)$/i.test(file.name)){PF.toast('Choose PNG, JPEG, WEBP, PDF or plain text, up to 1 MiB.');return;}
 const reader=new FileReader();reader.onerror=()=>PF.toast('Unable to read this file.');reader.onload=()=>{try{const asset={id:PF.id(),projectId:d.projectId,deliverableId:did,versionId:vid,name:text(file.name,250),mime:file.type,data:reader.result,size:file.size,createdAt:PF.now()};if(/[\x00-\x1f\x7f]/.test(asset.name))throw Error('Unsafe file name.');bytes(asset);PF.change(()=>{const live=deliverable(did);if(!live||latest(live).id!==vid)throw Error('A newer version appeared while reading. Choose the file again for the latest version.');if(latest(live).status!=='pending')throw Error('This version now has a decision. Submit a new version before attaching files.');asset.projectId=live.projectId;PF.w.assets.push(asset);PF.log('file','Attached a version file snapshot',live.projectId);},'File snapshot saved in this browser');}catch(err){PF.toast(err.message);}};reader.readAsDataURL(file);};input.click();
};
PF.actions['pf-file-download']=b=>{const a=PF.w.assets.find(a=>a.id===b.dataset.id);if(!a)throw Error('File not found.');const data=bytes(a),blob=new Blob([data],{type:a.mime}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=a.name;link.rel='noopener';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
PF.actions['pf-approval-report']=b=>{const d=deliverable(b.dataset.id);if(!d)throw Error('Deliverable not found.');PF.download('approval-report-'+d.id.replace(/[^a-z0-9-]/gi,'_')+'.json',JSON.stringify({scope:'Browser-local demo approval record; reference URLs may change externally. Attached snapshots preserve the local reviewed file.',exportedAt:PF.now(),deliverable:{id:d.id,title:d.title,projectId:d.projectId},versions:d.versions.map(v=>({...v,assets:filesFor(d,v).map(({data,...ref})=>ref)})),decisions:PF.db.approvals.filter(a=>a.deliverableId===d.id),comments:PF.w.comments.filter(c=>c.deliverableId===d.id)},null,2),'application/json');};
PF.views.files={title:'Files',icon:'▧',group:'work',render(){const items=PF.w.assets.filter(a=>!clientFilter||PF.project(a.projectId)?.clientId===clientFilter);return PF.heading('Files','Immutable file snapshots stored in this browser. Attach files from a deliverable before a review decision.')+`<label>Filter by client<select id="pf-files-client"><option value="">All clients</option>${PF.clientOptions().map(([id,name])=>`<option value="${E(id)}" ${id===clientFilter?'selected':''}>${E(name)}</option>`).join('')}</select></label><div class="project-grid space-top">${items.map(a=>{const d=deliverable(a.deliverableId),v=version(d,a.versionId);return `<section><p class="meta">${E(PF.project(a.projectId)?.name||'')} · ${E(d?d.title+' · v'+v.number:'Project file')}</p>${assetCards([a])}</section>`}).join('')||PF.empty('No file snapshots match this client.')}</div>`;}};
PF.onChange.push(event=>{const el=event.target;if(el.id==='pf-files-client'){clientFilter=el.value;PF.render();}if(el.dataset&&(el.dataset.pfCompare||el.dataset.pfTextfile)){const d=deliverable(el.dataset.deliverable);if(!d)return;const pair=comparisons.get(d.id)||[d.versions[Math.max(0,d.versions.length-2)].id,latest(d).id];if(el.dataset.pfCompare){if(!['a','b'].includes(el.dataset.pfCompare)||!version(d,el.value))return;pair[el.dataset.pfCompare==='a'?0:1]=el.value;}else{const side=el.dataset.pfTextfile;if(!['a','b'].includes(side))return;const v=version(d,pair[side==='a'?0:1]);if(!v||el.value&&!textFiles(d,v).some(a=>a.id===el.value))return;const choices=textChoices.get(d.id)||{};choices[side]={versionId:v.id,id:el.value};textChoices.set(d.id,choices);}comparisons.set(d.id,pair);PF.render();}});
})(window.PF);
